def conservar_consumo(apps, schema_editor):
    Factura = apps.get_model('facturacion', 'FacturaElectronica')
    Factura.objects.filter(estado__in=['EMITIDA', 'APROBADA', 'RECHAZADA']).update(consume_emision=True)
